import com.surprising.aeron.client.SurprisingAeronClient;
import com.surprising.aeron.protocol.*;
import com.surprising.product.api.ProductLine;
import java.time.Duration;
import java.util.List;
import java.util.UUID;

class AdlGate extends InsuranceGate {
    AdlGate(SurprisingAeronClient client) { super(client); }
    CoreUserStateView userState(long id) {
        return CoreStateQueryCodec.decodeUserState(query(CoreMessageType.USER_STATE_QUERY,id,new byte[0]));
    }
    @Override void execute() {
        var sourceWork=target(CoreLiquidationWorkView.Purpose.ADL);
        long covered=line==ProductLine.INVERSE_PERPETUAL?120:21;
        long close=line==ProductLine.INVERSE_PERPETUAL?4:2;
        var candidate=CoreAdlQueryCodec.decodeCandidates(query(CoreMessageType.ADL_CANDIDATE_QUERY,0,
                CoreAdlQueryCodec.encodeQuery(asset,100))).stream().filter(c->c.userId()==user(3)).findFirst().orElseThrow();
        if(sourceWork.deficitUnits()!=covered || candidate.signedQuantitySteps()!=-10
                || candidate.entryPriceTicks()!=100 || candidate.markPriceSequence()!=2
                || candidate.unrealizedProfitUnits()!=(line==ProductLine.INVERSE_PERPETUAL?300:200))
            throw new AssertionError("ADL fixture "+sourceWork+" "+candidate);
        var beforeTarget=userState(user(3));
        var beforeTreasury=CoreStateQueryCodec.decodeTreasuryState(query(CoreMessageType.TREASURY_STATE_QUERY,0,new byte[0]));
        var tooSmall=new ExecuteAdlCommand(sourceWork.liquidationId(),candidate.userId(),candidate.instrumentId(),
                candidate.marginMode(),candidate.positionSide(),candidate.signedQuantitySteps(),candidate.entryPriceTicks(),
                candidate.markPriceSequence(),1,covered);
        var rejected=command(CoreMessageType.EXECUTE_ADL,candidate.userId(),TradingCommandCodec.encodeExecuteAdl(tooSmall));
        if(rejected.commandStatus()!=ResponseStatus.REJECTED || !rejected.resultCode().name().equals("ADL_PROFIT_INSUFFICIENT"))
            throw new AssertionError("insufficient-profit ADL must reject: "+rejected.resultCode());
        if(!beforeTarget.equals(userState(user(3))) || !sourceWork.equals(target(CoreLiquidationWorkView.Purpose.ADL))
                || !beforeTreasury.equals(CoreStateQueryCodec.decodeTreasuryState(query(CoreMessageType.TREASURY_STATE_QUERY,0,new byte[0]))))
            throw new AssertionError("ADL rejection changed funds, position or source work");
        var valid=new ExecuteAdlCommand(sourceWork.liquidationId(),candidate.userId(),candidate.instrumentId(),
                candidate.marginMode(),candidate.positionSide(),candidate.signedQuantitySteps(),candidate.entryPriceTicks(),
                candidate.markPriceSequence(),close,covered);
        UUID id=UUID.randomUUID();long commandSequence=++sequence;
        var message=new CoreMessage(CoreMessageHeader.command(CoreMessageType.EXECUTE_ADL,id,line,
                CommandSource.OPERATIONS,source,commandSequence,candidate.userId(),commandSequence,commandSequence),
                TradingCommandCodec.encodeExecuteAdl(valid));
        var response=client.submit(message);
        if(response.commandStatus()!=ResponseStatus.APPLIED) throw new AssertionError("ADL "+response.resultCode());
        long hash=CoreStateQueryCodec.decodeStateHash(query(CoreMessageType.STATE_HASH_QUERY,0,new byte[0]));
        var duplicate=client.submit(message);
        if(duplicate.status()!=ResponseStatus.DUPLICATE || hash!=CoreStateQueryCodec.decodeStateHash(query(CoreMessageType.STATE_HASH_QUERY,0,new byte[0])))
            throw new AssertionError("ADL duplicate changed state");
    }
    @Override void verify() {
        if(work(CoreLiquidationWorkView.Purpose.ADL).resolutions().stream().anyMatch(r->r.userId()==user(4))
                || work(CoreLiquidationWorkView.Purpose.INSURANCE).resolutions().stream().anyMatch(r->r.userId()==user(4))
                || work(CoreLiquidationWorkView.Purpose.EXECUTION).actions().stream().anyMatch(r->r.userId()==user(4)))
            throw new AssertionError("covered source remains pending");
        var target=userState(user(3));
        var position=target.positions().stream().filter(p->p.instrumentId().equals("1")).findFirst().orElseThrow();
        long expectedQuantity=line==ProductLine.INVERSE_PERPETUAL?-6:-8;
        long expectedMargin=line==ProductLine.INVERSE_PERPETUAL?6:80;
        long expectedRealized=line==ProductLine.INVERSE_PERPETUAL?120:40;
        long expectedTotal=line==ProductLine.INVERSE_PERPETUAL?179:198;
        long total=target.balances().stream().filter(b->b.asset().equals(asset)).mapToLong(b->Math.addExact(b.availableUnits(),b.lockedUnits())).sum();
        if(position.signedQuantitySteps()!=expectedQuantity || position.positionMarginUnits()!=expectedMargin
                || position.realizedPnlUnits()!=expectedRealized || total!=expectedTotal) throw new AssertionError("ADL target "+target);
        var treasury=CoreStateQueryCodec.decodeTreasuryState(query(CoreMessageType.TREASURY_STATE_QUERY,0,new byte[0])).stream()
                .filter(t->t.asset().equals(asset)).findFirst().orElseThrow();
        long expectedClearing=line==ProductLine.INVERSE_PERPETUAL?1:-18;
        if(treasury.insuranceBalanceUnits()!=0 || treasury.insuranceDeficitUnits()!=0 || treasury.clearingPnlBalanceUnits()!=expectedClearing)
            throw new AssertionError("ADL ledger "+treasury);
        long funds=economicFunds();
        if(funds!=(line==ProductLine.INVERSE_PERPETUAL?2182:2183)) throw new AssertionError("ADL funds "+funds);
        System.out.println("ADL_GATE_PASS product="+line+" insufficientProfitRejected=true duplicateStable=true sourcePending=0 insuranceDeficit=0 targetQuantity="+expectedQuantity+" targetMargin="+expectedMargin+" fundsDifference=0");
    }
    public static void main(String[] args) {
        try(var client=SurprisingAeronClient.connect(ProductLine.requireExternalCode(System.getProperty("surprising.aeron.product-line")),
                List.of("127.0.0.1"),"127.0.0.1",Duration.ofSeconds(10))) {
            var gate=new AdlGate(client);
            if(!System.getProperty("round69.adl-mode","execute").equals("verify")) gate.execute();
            gate.verify();
        }
    }
}

