import io.aeron.CommonContext;
import io.aeron.cluster.RecordingLog;
import java.io.File;

class RuntimeCheck {
    public static void main(String[] args) {
        if (args[0].equals("driver")) {
            if (CommonContext.isDriverActive(new File(args[1]), CommonContext.DRIVER_TIMEOUT_MS, ignored -> {})) {
                throw new IllegalStateException("old MediaDriver is active");
            }
            System.out.println("DRIVER_INACTIVE");
        } else {
            try (var log = new RecordingLog(new File(args[1]), false)) {
                for (int service : new int[] {0, -1}) {
                    long count = log.entries().stream().filter(e -> e.isValid
                            && e.type == RecordingLog.ENTRY_TYPE_SNAPSHOT && e.serviceId == service).count();
                    System.out.println("SNAPSHOT_COUNT service=" + service + " count=" + count);
                }
            }
        }
    }
}

